<template><main data-ui-id="widget-root" class="widget-root" @keydown.esc="collapse"><FloatingOrb v-if="!isExpanded" :quota="state.quota" :expanded="false" @toggle="toggle"/><template v-else><OverviewPanel :state="state" :status-label="statusLabel" :busy="busy" @refresh="load" @close="collapse"><QuotaPanel :quota="state.quota"/><TodayPanel :today="state.today" :buckets="state.heatmap24h?.buckets" :selected="selected?.key" @select="selectHour"/><TodayAndTrendPanels :heatmap="state.heatmap7d" :trend="state.trend30d"/></OverviewPanel><FloatingOrb :quota="state.quota" expanded @toggle="toggle"/></template><div v-if="state.errorText" class="state-banner">{{state.errorText}}</div></main></template>
<script setup>import {useWidgetStore} from './state/widget.js';import FloatingOrb from './components/FloatingOrb.vue';import OverviewPanel from './components/OverviewPanel.vue';import QuotaPanel from './components/QuotaPanel.vue';import TodayPanel from './components/TodayPanel.vue';import TodayAndTrendPanels from './components/TodayAndTrendPanels.vue';const {state,busy,selected,isExpanded,statusLabel,load,toggle,collapse}=useWidgetStore();function selectHour(key){selected.value=selected.value?.key===key?null:{kind:'hour',key}}</script>
